    title: "建設・介護業界SNS採用コンテンツカレンダー作成ガイド2027｜年間投稿計画の立て方",
    description: "建設・介護業界がSNS採用コンテンツカレンダーを作成する方法。季節・採用サイクルに合わせた年間投稿計画の立て方と継続するためのコツを解説します。",
